#include <bits/stdc++.h>
using namespace std;

int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);

        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v;
            scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }

        // Root tree at 1, compute parent, subtree membership
        vector<int> par(n+1,-1), depth(n+1,0), order;
        vector<bool> vis(n+1,false);
        queue<int> q;
        q.push(1); vis[1]=true;
        while(!q.empty()){
            int u=q.front();q.pop();
            order.push_back(u);
            for(auto [v,ei]:adj[u]) if(!vis[v]){
                vis[v]=true; par[v]=u; depth[v]=depth[u]+1;
                q.push(v);
            }
        }

        // For edge i=(u,v), determine which side each node is on
        // subtree[v] when we remove edge: nodes in subtree of child
        // For each edge, find if removing it, which subtree contains a given node
        // We'll use LCA-based approach: for edge (u,v) where v is child of u,
        // node x is in v's subtree iff v is ancestor of x

        // Precompute subtree ranges for ancestor checks
        vector<int> tin(n+1), tout(n+1);
        int timer=0;
        // DFS order
        function<void(int)> dfs=[&](int u){
            tin[u]=timer++;
            for(auto [v,ei]:adj[u]) if(v!=par[u]){
                dfs(v);
            }
            tout[u]=timer++;
        };
        dfs(1);
        auto isAnc=[&](int u, int v)->bool{ return tin[u]<=tin[v]&&tout[v]<=tout[u]; };

        vector<vector<int>> results;
        for(int iter=0;iter<2*n&&iter<2000;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;

            // Find happy edges: both values want to cross
            vector<int> happy;
            for(int i=0;i<n-1;i++){
                int u=edges[i].first, v=edges[i].second;
                // Make u parent of v
                int child=v, parent=u;
                if(par[u]==v){child=u;parent=v;}
                // p[child] wants to go to target p[child]. Is target outside child's subtree?
                bool childValGoesUp = !isAnc(child, p[child]);
                // p[parent] wants to go to target p[parent]. Is target inside child's subtree?
                bool parValGoesDown = isAnc(child, p[parent]);
                if(childValGoesUp && parValGoesDown) happy.push_back(i);
            }

            // Greedy maximum matching on happy edges
            // Use random shuffle for variety, then greedy
            // Actually let's do proper max matching on tree subset
            vector<bool> used(n+1,false);
            vector<int> matching;
            // Prioritize by some heuristic - e.g., deeper edges first (leaves)
            sort(happy.begin(), happy.end(), [&](int a, int b){
                int da=max(depth[edges[a].first],depth[edges[a].second]);
                int db=max(depth[edges[b].first],depth[edges[b].second]);
                return da>db;
            });
            for(int ei:happy){
                int u=edges[ei].first, v=edges[ei].second;
                if(!used[u]&&!used[v]){
                    used[u]=used[v]=true;
                    matching.push_back(ei);
                    swap(p[u],p[v]);
                }
            }
            if(matching.empty()){
                // No happy edges - force a swap on any edge where both aren't sorted
                for(int i=0;i<n-1;i++){
                    int u=edges[i].first, v=edges[i].second;
                    if(p[u]!=u && p[v]!=v){
                        matching.push_back(i);
                        swap(p[u],p[v]);
                        break;
                    }
                }
                if(matching.empty()){
                    for(int i=0;i<n-1;i++){
                        int u=edges[i].first, v=edges[i].second;
                        if(p[u]!=u||p[v]!=v){
                            matching.push_back(i);
                            swap(p[u],p[v]);
                            break;
                        }
                    }
                }
            }
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto &m:results){
            printf("%d",(int)m.size());
            for(int ei:m) printf(" %d",ei+1);
            printf("\n");
        }
    }
}
